"""Record actual review of all twenty prospective TRAIN houseplant originals."""
import hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
NOTES={133252835: 'Advertising interior composite; plant container occluded behind sofa, real/artificial/composite status uncertain. Hold.', 36094969: 'Palm foliage close view above dense lower planting; no identifiable container extent and multiple plant ownership. Hold.', 82690560: 'Visible flowering soil pot, but publisher ImageDescription explicitly says MISTAKE - PLEASE DELETE. Exclude from adoption despite listed CC BY-SA4.', 118818738: 'Single white rooted succulent container, left/top foliage partly clipped. Rear wooden bowl contains stones with no visible vegetation; candidate single instance.', 85912518: 'Single tall soil-filled planted container with full foliage and pot visible. Aquarium vegetation is outside terrestrial potted-container scope; candidate.', 169001494: 'Cat on highly cropped plant pot; trunk and foliage clipped on several edges, instance extent uncertainty. Hold.', 17292499: 'Flower macro with only tiny container edge and unclear independent roots/instances. Hold.', 146412608: 'Two-panel plant before/after collage with multiple pots; not natural camera frame. Hold.', 191189257: 'Text infographic with composited plant illustration; creator link missing, unsuitable natural-camera positive. Hold.', 160559990: 'Foreground white orchid versus rear bonsai container ownership unclear; multiple targets with extensive clipping. Hold.', 99283902: 'Portrait among dense occluded plants and cut flowers; complete-instance census uncertain. Hold.', 148667846: 'Main aloe in green soil pot clear but separate right-side plant container absent/occluded. Full census hold.', 75811359: 'Multiple overlapping cyclamen pots and clipped edge containers; historical creator hit. Hold.', 80137834: 'Two terrestrial rooted indoor plants in silver pots; left is clipped by image edge. Candidate two instances.', 18017884: 'Single rooted anthurium in green container against plain background; candidate one instance.', 128769371: 'Single rooted red-flowering plant in red pot on patterned table; candidate one instance.', 88034041: 'Single soil-rooted plant in red ceramic pot; side leaves clipped, painted floral background is not an additional live plant. Candidate one instance.', 131341191: 'Sprout macro in moss with no identifiable container; no negative label inferred. Hold.', 111886037: 'Cat among several partly clipped succulents and cactus pots; occlusion and complete-instance census hold.', 77816798: 'Single aloe in soil pot by window; leaf tips clipped by top/side image boundaries. Candidate one instance.'}
CANDIDATES=[118818738,85912518,80137834,18017884,128769371,88034041,77816798]
def main():
 source=ROOT/'Datasets/plant-houseplant-train-source-v73';manifest=source/'manifest.json';data=json.loads(manifest.read_text());assert len(data['samples'])==20
 rows=[]
 for r in data['samples']:
  assert hashlib.sha256((source/r['image']).read_bytes()).hexdigest()==r['sha256']
  rows.append(dict(page_id=r['page_id'],image=r['image'],sha256=r['sha256'],observation=NOTES[r['page_id']],original_actually_viewed=True,annotation_approved=False,reserved_split='train'))
 out=ROOT/'Reports/plant-houseplant-train-v73-original-review.json';assert not out.exists();out.write_text(json.dumps(dict(samples=rows,candidate_page_ids=CANDIDATES,held_page_ids=[r['page_id'] for r in rows if r['page_id'] not in CANDIDATES],publisher_requested_deletion_excluded=[82690560],source_manifest_sha256=hashlib.sha256(manifest.read_bytes()).hexdigest(),training_approved=False,deployment_accepted=False),indent=2),encoding='utf-8');print('All20 originals actually reviewed; seven annotation candidates, thirteen holds')
if __name__=='__main__':main()
